/**
 * Generate a database seed script template
 */
export function generateDatabaseSeed(profile: ProjectProfile): string {
  const { architecture, crossCuttingConcerns } = profile;
  const entityName = architecture.primaryEntity;
  const capitalizedEntity =
    entityName.charAt(0).toUpperCase() + entityName.slice(1);
  const hasRoles = crossCuttingConcerns.auth.requiresRoles;

  return `/**
 * SPDX-License-Identifier: MIT
 *
 * Database seed script
 * Generated by Zopio Project Setup MCP
 *
 * Usage:
 *   npx tsx packages/database/seed.ts
 *
 * This script creates initial test data for development.
 */

import { PrismaClient } from './generated/client';

const prisma = new PrismaClient();

async function seed() {
  console.log('🌱 Starting database seed...');

  // Create a test user
  const user = await prisma.user.upsert({
    where: { email: 'test@example.com' },
    update: {},
    create: {
      clerkId: 'user_test_123',
      email: 'test@example.com',
      name: 'Test User',${hasRoles ? "\n      role: 'admin'," : ''}
    },
  });
  console.log('✅ Created test user:', user.email);

  // Create a test ${entityName}
  const ${entityName} = await prisma.${entityName}.upsert({
    where: { slug: 'test-${entityName}' },
    update: {},
    create: {
      name: 'Test ${capitalizedEntity}',
      slug: 'test-${entityName}',
      description: 'A test ${entityName} for development',
    },
  });
  console.log('✅ Created test ${entityName}:', ${entityName}.slug);

  // Create membership linking user to ${entityName}
  await prisma.membership.upsert({
    where: {
      userId_${entityName}Id: {
        userId: user.id,
        ${entityName}Id: ${entityName}.id,
      },
    },
    update: {},
    create: {
      userId: user.id,
      ${entityName}Id: ${entityName}.id,${hasRoles ? "\n      role: 'admin'," : ''}
    },
  });
  console.log('✅ Created membership for user in ${entityName}');

  console.log('\\n🎉 Database seed completed!');
}

seed()
  .catch((error) => {
    console.error('❌ Seed failed:', error);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
`;
}

/**
 * Generate a basic PROJECT_SETUP.md summary file
 */
export function generateSetupSummaryDoc(profile: ProjectProfile): string {
  const { metadata, selectedApps, architecture, crossCuttingConcerns } =
    profile;

  const apps = Object.entries(selectedApps)
    .filter(([, enabled]) => enabled)
    .map(([name]) => `apps/${name}`)
    .join(', ');

  const features: string[] = [];
  if (crossCuttingConcerns.auth.enabled) {
    features.push('Authentication (Clerk)');
  }
  if (crossCuttingConcerns.observability.enabled) {
    features.push('Observability (Sentry/Logtail)');
  }
  if (crossCuttingConcerns.analytics.enabled) {
    features.push('Analytics');
  }
  if (crossCuttingConcerns.storage.enabled) {
    features.push('Storage (Vercel Blob)');
  }
  if (crossCuttingConcerns.rateLimit.enabled) {
    features.push('Rate Limiting (Upstash)');
  }

  return `# Project Setup Summary

This project was bootstrapped using the Zopio Project Setup MCP.

## Project Information

- **Name**: ${metadata.name}
- **Description**: ${metadata.description || 'N/A'}
- **Target Users**: ${metadata.targetUsers}

## Architecture

- **Tenancy Model**: ${architecture.tenancyModel}
- **Primary Entity**: ${architecture.primaryEntity}

## Selected Apps

${apps}

## Enabled Features

${features.map((f) => `- ${f}`).join('\n')}

## Next Steps

1. Configure environment variables in each app's \`.env.local\` file
2. Run \`pnpm migrate\` to set up the database schema
3. Review and customize the generated wiring code
4. Start development with \`pnpm dev\`

## Environment Variables

Make sure to set up the following required environment variables:

- \`DATABASE_URL\`: Neon PostgreSQL connection string
${crossCuttingConcerns.auth.enabled ? '- `CLERK_SECRET_KEY`: Clerk secret key\n- `NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY`: Clerk publishable key' : ''}
${crossCuttingConcerns.observability.enabled ? '- `NEXT_PUBLIC_SENTRY_DSN`: Sentry DSN' : ''}
${crossCuttingConcerns.analytics.posthog ? '- `NEXT_PUBLIC_POSTHOG_KEY`: PostHog API key\n- `NEXT_PUBLIC_POSTHOG_HOST`: PostHog host' : ''}
${crossCuttingConcerns.storage.enabled ? '- `BLOB_READ_WRITE_TOKEN`: Vercel Blob token' : ''}
${crossCuttingConcerns.rateLimit.enabled ? '- `UPSTASH_REDIS_REST_URL`: Upstash Redis URL\n- `UPSTASH_REDIS_REST_TOKEN`: Upstash Redis token' : ''}

---
Generated on: ${new Date().toISOString()}
`;
}
